import React, { useState } from "react";


function DisputeForm({
    onCreated
}) {


    const [subject, setSubject] =
        useState("");


    const [gradeDate, setGradeDate] =
        useState("");


    const [reason, setReason] =
        useState("");


    const [submitting, setSubmitting] =
        useState(false);


    /*
        Get today's date
    */
    const getToday = () => {

        const today =
            new Date();


        const year =
            today.getFullYear();


        const month =
            String(
                today.getMonth() + 1
            ).padStart(2, "0");


        const day =
            String(
                today.getDate()
            ).padStart(2, "0");


        return `${year}-${month}-${day}`;

    };


    /*
        Submit form
    */
    const handleSubmit = async (
        event
    ) => {

        event.preventDefault();


        /*
            Frontend validation
        */
        if (
            !subject ||
            !gradeDate ||
            !reason.trim()
        ) {

            return;

        }


        try {

            setSubmitting(true);


            /*
                Send data to parent
            */
            await onCreated({

                subject:
                    subject,

                grade_date:
                    gradeDate,

                reason:
                    reason.trim()

            });


            /*
                Clear form
            */
            setSubject("");

            setGradeDate("");

            setReason("");


        } catch (error) {

            console.error(error);

        } finally {

            setSubmitting(false);

        }

    };


    return (

        <div className="form-card">


            {/* Header */}

            <div className="card-header">


                <div>

                    <h3>
                        Raise a Dispute
                    </h3>

                    <p>
                        Provide the details of your grade concern.
                    </p>

                </div>


                <div className="form-icon">

                    📝

                </div>


            </div>


            {/* Form */}

            <form
                onSubmit={handleSubmit}
            >


                {/* Subject */}

                <div className="form-group">

                    <label htmlFor="subject">

                        Subject

                    </label>


                    <select
                        id="subject"
                        value={subject}
                        onChange={
                            event =>
                                setSubject(
                                    event.target.value
                                )
                        }
                        required
                    >

                        <option value="">

                            Select a subject

                        </option>


                        <option value="Java Programming">

                            Java Programming

                        </option>


                        <option value="Database Management Systems">

                            Database Management Systems

                        </option>


                        <option value="Computer Networks">

                            Computer Networks

                        </option>


                        <option value="Operating Systems">

                            Operating Systems

                        </option>


                        <option value="Web Development">

                            Web Development

                        </option>


                    </select>

                </div>


                {/* Grade Date */}

                <div className="form-group">

                    <label htmlFor="gradeDate">

                        Grade Received Date

                    </label>


                    <input
                        id="gradeDate"
                        type="date"
                        value={gradeDate}
                        max={getToday()}
                        onChange={
                            event =>
                                setGradeDate(
                                    event.target.value
                                )
                        }
                        required
                    />


                    <small>

                        Disputes must be raised within
                        30 days of receiving the grade.

                    </small>

                </div>


                {/* Reason */}

                <div className="form-group">


                    <div className="label-row">


                        <label htmlFor="reason">

                            Reason for Dispute

                        </label>


                        <span>

                            {reason.length} / 1000

                        </span>


                    </div>


                    <textarea
                        id="reason"
                        rows="7"
                        maxLength="1000"
                        value={reason}
                        placeholder="Explain why you believe the grade should be reviewed..."
                        onChange={
                            event =>
                                setReason(
                                    event.target.value
                                )
                        }
                        required
                    />


                </div>


                {/* Warning */}

                <div className="warning-box">


                    <span>
                        ⚠️
                    </span>


                    <div>

                        <strong>
                            Important
                        </strong>


                        <p>
                            Only one open dispute is allowed
                            for the same subject at a time.
                        </p>

                    </div>


                </div>


                {/* Submit */}

                <button
                    type="submit"
                    className="submit-button"
                    disabled={submitting}
                >

                    {submitting
                        ? "Submitting..."
                        : "Submit Dispute"
                    }

                </button>


            </form>

        </div>

    );

}


export default DisputeForm;
